def fix_seller_without_provider(apps, schema_editor):
    """
    Talleres con commerce_level='SELLER' pero sin provider asignado violan
    la regla de negocio. Se degradan a 'B2B_BUYER' para que el constraint
    pueda aplicarse sin perder datos.
    """
    Workshop = apps.get_model('services', 'Workshop')
    Workshop.objects.filter(
        commerce_level='SELLER',
        provider__isnull=True,
    ).update(commerce_level='B2B_BUYER')


def fix_duplicate_vehicle_expertise(apps, schema_editor):
    """
    Elimina registros duplicados de WorkshopVehicleExpertise por (workshop, modelo)
    conservando el de mayor id (el más reciente) en cada grupo.
    El mismo patrón se aplica a (workshop, marca) aunque actualmente no hay casos.
    """
    from django.db.models import Count

    WorkshopVehicleExpertise = apps.get_model('services', 'WorkshopVehicleExpertise')

    # Duplicados por modelo
    dup_modelo = (
        WorkshopVehicleExpertise.objects
        .filter(modelo__isnull=False)
        .values('workshop_id', 'modelo_id')
        .annotate(n=Count('id'))
        .filter(n__gt=1)
    )
    for group in dup_modelo:
        keep = (
            WorkshopVehicleExpertise.objects
            .filter(workshop_id=group['workshop_id'], modelo_id=group['modelo_id'])
            .order_by('-id')
            .values_list('id', flat=True)
            .first()
        )
        WorkshopVehicleExpertise.objects.filter(
            workshop_id=group['workshop_id'],
            modelo_id=group['modelo_id'],
        ).exclude(id=keep).delete()

    # Duplicados por marca (sin modelo)
    dup_marca = (
        WorkshopVehicleExpertise.objects
        .filter(marca__isnull=False, modelo__isnull=True)
        .values('workshop_id', 'marca_id')
        .annotate(n=Count('id'))
        .filter(n__gt=1)
    )
    for group in dup_marca:
        keep = (
            WorkshopVehicleExpertise.objects
            .filter(workshop_id=group['workshop_id'], marca_id=group['marca_id'], modelo__isnull=True)
            .order_by('-id')
            .values_list('id', flat=True)
            .first()
        )
        WorkshopVehicleExpertise.objects.filter(
            workshop_id=group['workshop_id'],
            marca_id=group['marca_id'],
            modelo__isnull=True,
        ).exclude(id=keep).delete()


